def has_close_elements(numbers: List[float], threshold: float) -> bool:
    if len(numbers) < 2:
        return False

    numbers.sort()
    for i in range(len(numbers) - 1):
        if math.isclose(numbers[i], numbers[i + 1], abs_tol=threshold):
            return True

    return False
