def tri(n):
    trib_sequence = [0] * (n + 1)
    trib_sequence[1] = 3
    trib_sequence[2] = 1 + (2 / 2)

    for i in range(3, n + 1):
        if i % 2 == 0:
            trib_sequence[i] = 1 + (i / 2)
        else:
            trib_sequence[i] = trib_sequence[i - 1] + trib_sequence[i - 2] + trib_sequence[i - 3]

